SELECT s1."c0" AS "id", s1."c1" AS "__weight" FROM ((SELECT s2."c0" AS "c0", s2."c1" AS "c1" FROM (SELECT s3."c0" AS "c0", s3."c3" AS "c1" FROM (SELECT "id" AS "c0", "customer" AS "c1", "amount" AS "c2", "__weight" AS "c3" FROM "orders$delta") AS s3) AS s2) UNION ALL (SELECT s4."c0" AS "c0", s4."c1" AS "c1" FROM (SELECT s5."c0" AS "c0", s5."c3" AS "c1" FROM (SELECT s6."c0" AS "c0", s6."c1" AS "c1", s6."c2" AS "c2", s6."c3" AS "c3" FROM (SELECT "id" AS "c0", "customer" AS "c1", "amount" AS "c2", "__weight" AS "c3" FROM "orders$delta") AS s6 WHERE (s6."c2" < 3)) AS s5) AS s4)) AS s1
